using HotelManagement.Application.Abstractions.Notifications;using HotelManagement.Application.Abstractions.Persistence;using HotelManagement.Domain.Modules.Notifications.Entities;namespace HotelManagement.Infrastructure.Notifications;public sealed class NotificationPublisher(IApplicationDbContext db):INotificationPublisher{public async Task PublishAsync(Guid hotelId,Guid? userId,string title,string message,CancellationToken ct=default){db.Notifications.Add(new Notification(hotelId,userId,title,message));await db.SaveChangesAsync(ct);}}
